  igdb_id = 116584, title = 'The Lord of the Rings: Gollum',
  cover_url = 'https://images.igdb.com/igdb/image/upload/t_cover_big_2x/co4sdl.jpg', cover_image_id = 'co4sdl',
  released_on = '2023-05-25', release_year = 2023,
